        return f"data/futures/um/monthly/klines/{symbol}/1h/"
    if dataset == "spot_1h":
        return f"data/spot/monthly/klines/{symbol}/1h/"
    if dataset == "funding":
        return f"data/futures/um/monthly/fundingRate/{symbol}/"
    raise ValueError(dataset)


